var n=`0978-haemul-pajeon`;var a=`world-0978`;var s=`KR`;var o=`east-asia`;var t=8;var r=42;var l={en:`Haemul Pajeon`,ua:`Хемуль паджон`};var u={en:`Haemul Pajeon is a South Korea dish made with shrimp, squid, green onion, all-purpose flour. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Хемуль паджон, страва кухні країни Південна Корея. Основні складники: креветка, кальмар, зелена цибуля, пшеничне борошно універсальне. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`shrimp`,310,`g`],[`squid`,270,`g`],[`green-onion`,270,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`all-purpose-flour`,230,`g`],[`water`,285,`ml`],[`chicken-egg`,2,`pcs`],[`table-salt`,4,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 20 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 20 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:20,i:[[`canola-oil`,75,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`light-soy-sauce`,40,`ml`],[`rice-vinegar`,30,`ml`]]}];var g={slug:n,id:a,country:`KR`,region:o,servings:8,minutes:42,title:l,text:u,steps:d};export{s as country,g as default,a as id,r as minutes,o as region,t as servings,n as slug,d as steps,u as text,l as title};